  public setHasDebugged(value: boolean): void {
    this.hasDebugged = value
  }

  public getHasDebugged(): boolean {
    return this.hasDebugged
  }

  public setUndetectable(state: boolean): void {
    // Guard: skip if state hasn't actually changed to prevent
    // duplicate dock hide/show cycles from renderer feedback loops
    if (this.isUndetectable === state) return;

    console.log(`[Stealth] setUndetectable(${state}) called`);

    this.isUndetectable = state
    this.windowHelper.setContentProtection(state)
    this.settingsWindowHelper.setContentProtection(state)
    this.modelSelectorWindowHelper.setContentProtection(state)
    this.cropperWindowHelper.setContentProtection(state)

    // Persist state via SettingsManager
    SettingsManager.getInstance().set('isUndetectable', state);

    // Zoom-detection fallback is intentionally NOT auto-started here.
    // With content protection now working (opaque launcher window), Saumya
    // only sees a dark rectangle, not the actual UI — and the user wants to
    // be able to see Natively themselves during Zoom calls. Call
    // startZoomDetection() explicitly only if a future "extra stealth" mode
    // is added that fully hides the launcher when Zoom is open.

